const resposta = await session.datasources["API-INSTANCIAS"];

let dados = resposta;

// ==========================================
// NORMALIZA JSON
// ==========================================

if (typeof dados === "string") {
    try {
        dados = JSON.parse(dados);
    } catch (e) {
        return {
            sucesso: false,
            erro: "Resposta não é um JSON válido",
            detalhe: String(e)
        };
    }
}

function encontrarArray(obj) {
    if (Array.isArray(obj)) return obj;
    if (!obj || typeof obj !== "object") return null;
    if (Array.isArray(obj.resultados)) return obj.resultados;
    if (Array.isArray(obj.data)) return obj.data;
    for (const chave of Object.keys(obj)) {
        const valor = obj[chave];
        if (valor && typeof valor === "object") {
            const encontrado = encontrarArray(valor);
            if (encontrado) return encontrado;
        }
    }
    return null;
}

const lista = encontrarArray(dados);

if (!lista || lista.length === 0) {
    return { sucesso: false, total: 0, erro: "Nenhum resultado encontrado" };
}

function tierParaNumero(tier) {
    if (!tier) return null;
    const valor = String(tier).toUpperCase();
    if (valor.includes("2K")) return 2000;
    if (valor.includes("250")) return 250;
    if (valor.includes("1K")) return 1000;
    if (valor.includes("10K")) return 10000;
    if (valor.includes("100K")) return 100000;
    return null;
}

// ==========================================
// STATUS REAIS DE BLOQUEIO/BANIMENTO NA META
// (isso sim é crítico — diferente de "nome reprovado")
// ==========================================

const STATUS_CRITICOS = ["BANNED", "RESTRICTED", "FLAGGED", "RATE_LIMITED", "DISABLED"];
const STATUS_ATENCAO = ["PENDING_DELETION", "MIGRATED", "DELETED"];

const GRAPH_VERSION = "v20.0";

async function buscarDadosNumero(phoneNumberId, token) {
    if (!phoneNumberId || !token) {
        return {
            messaging_limit_tier: null,
            quality_rating: null,
            status_graph: null,
            name_status: null,
            throughput: null,
            erroGraph: "sem phoneNumberId ou token"
        };
    }

    try {
        // messaging_limit_tier foi DEPRECIADO pela Meta.
        // Campo correto atual: whatsapp_business_manager_messaging_limit
        const url = `https://graph.facebook.com/${GRAPH_VERSION}/${phoneNumberId}?fields=quality_rating,whatsapp_business_manager_messaging_limit,status,name_status,throughput`;
        const resp = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
        const json = await resp.json();

        if (json.error) {
            return {
                messaging_limit_tier: null,
                quality_rating: null,
                status_graph: null,
                name_status: null,
                throughput: null,
                erroGraph: json.error.message || "erro desconhecido na Graph API"
            };
        }

        return {
            messaging_limit_tier: json.whatsapp_business_manager_messaging_limit || null,
            quality_rating: json.quality_rating || null,
            status_graph: json.status || null,
            name_status: json.name_status || null,
            throughput: json.throughput?.level || null,
            erroGraph: null
        };
    } catch (e) {
        return {
            messaging_limit_tier: null,
            quality_rating: null,
            status_graph: null,
            name_status: null,
            throughput: null,
            erroGraph: String(e)
        };
    }
}

async function buscarMensagensEnviadas24h(wabaId, token) {
    if (!wabaId || !token) {
        return { enviadas24h: null, erroAnalytics: "sem wabaId ou token" };
    }
    try {
        const agora = Math.floor(Date.now() / 1000);
        const ontem = agora - 86400;
        const url = `https://graph.facebook.com/${GRAPH_VERSION}/${wabaId}?fields=analytics.start(${ontem}).end(${agora}).granularity(DAY)`;
        const resp = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
        const json = await resp.json();

        if (json.error) {
            return { enviadas24h: null, erroAnalytics: json.error.message || "sem permissão de analytics" };
        }

        const pontos = json.analytics?.data_points || [];
        const totalEnviadas = pontos.reduce((soma, p) => soma + (Number(p.sent) || 0), 0);
        return { enviadas24h: totalEnviadas, erroAnalytics: null };
    } catch (e) {
        return { enviadas24h: null, erroAnalytics: String(e) };
    }
}

const TAMANHO_LOTE = 10;

async function processarEmLotes(itens, tamanhoLote, fn) {
    const resultado = [];
    for (let i = 0; i < itens.length; i += tamanhoLote) {
        const lote = itens.slice(i, i + tamanhoLote);
        const respostasLote = await Promise.all(lote.map(fn));
        resultado.push(...respostasLote);
    }
    return resultado;
}

const resultados = await processarEmLotes(lista, TAMANHO_LOTE, async (item) => {

    const wabaId = item.wabaId || item.config?.wabaId || null;
    const businessId = item.businessId || item.config?.businessId || null;
    const phoneNumber = item.phoneNumber || item.config?.phoneNumber || null;
    const phoneNumberId = item.phoneNumberId || item.config?.phoneNumberId || null;
    const token = item.config?.token || null;
    const statusCrm = item.status || null;

    const [dadosNumero, dadosAnalytics] = await Promise.all([
        buscarDadosNumero(phoneNumberId, token),
        buscarMensagensEnviadas24h(wabaId, token)
    ]);

    const limite = dadosNumero.messaging_limit_tier || item.limite || null;
    const limiteNumerico = tierParaNumero(limite);
    const enviadas24h = dadosAnalytics.enviadas24h;

    let limiteZerado = false;
    let percentualUsado = null;
    if (limiteNumerico && enviadas24h !== null) {
        percentualUsado = Math.round((enviadas24h / limiteNumerico) * 100);
        limiteZerado = enviadas24h >= limiteNumerico;
    }

    // ======================================
    // CLASSIFICAÇÃO CORRETA (sem misturar conceitos)
    // ======================================

    const banidoOuRestrito = STATUS_CRITICOS.includes(dadosNumero.status_graph);
    const emAtencaoMeta = STATUS_ATENCAO.includes(dadosNumero.status_graph);
    const nomeReprovado = dadosNumero.name_status === "DECLINED";

    return {
        id: item.id || null,
        nome: item.name || null,
        phoneNumber,
        phoneNumberId,
        wabaId,
        businessId,

        ativo: item.isActive === true || item.ativo === true,
        statusCrm,
        conectado: statusCrm === "CONNECTED",

        statusMeta: dadosNumero.status_graph,
        nameStatus: dadosNumero.name_status,
        throughput: dadosNumero.throughput,

        banidoOuRestrito,
        emAtencaoMeta,
        nomeReprovado,

        qualidade: dadosNumero.quality_rating,

        limite,
        limiteNumerico,
        enviadas24h,
        percentualUsado,
        limiteZerado,

        erro: item.erro || dadosNumero.erroGraph || null,
        erroAnalytics: dadosAnalytics.erroAnalytics
    };
});

// ==========================================
// CLASSIFICAÇÃO POR SEVERIDADE (3 NÍVEIS CLAROS)
// ==========================================

for (const item of resultados) {
    const critico = [];
    const atencao = [];
    const info = [];

    if (item.banidoOuRestrito) critico.push("BANIDO_OU_RESTRITO_META");
    if (item.limiteZerado) critico.push("LIMITE_DIARIO_ZERADO");
    if (item.qualidade === "RED") critico.push("QUALIDADE_RED");
    if (item.erro) critico.push("ERRO_CONSULTA_GRAPH");

    if (item.emAtencaoMeta) atencao.push("STATUS_META_" + item.statusMeta);
    if (item.nomeReprovado) atencao.push("NOME_EXIBICAO_REPROVADO");
    if (item.qualidade === "UNKNOWN" || !item.qualidade) atencao.push("QUALIDADE_AINDA_NAO_AVALIADA");
    if (!item.conectado) atencao.push("DESCONECTADO");
    if (!item.ativo) atencao.push("INATIVO");

    if (!item.phoneNumber) info.push("SEM_TELEFONE_CADASTRADO");
    if (!item.limite) info.push("SEM_TIER_ATRIBUIDO_AINDA");

    item.critico = critico;
    item.atencao = atencao;
    item.info = info;

    item.nivel = critico.length > 0 ? "CRITICO" : atencao.length > 0 ? "ATENCAO" : "OK";

    delete item.banidoOuRestrito;
    delete item.emAtencaoMeta;
    delete item.nomeReprovado;
}

const ordemNivel = { CRITICO: 0, ATENCAO: 1, OK: 2 };
resultados.sort((a, b) => ordemNivel[a.nivel] - ordemNivel[b.nivel]);

// ==========================================
// INDICADORES GERAIS
// ==========================================

const total = resultados.length;
const criticos = resultados.filter(x => x.nivel === "CRITICO");
const emAtencao = resultados.filter(x => x.nivel === "ATENCAO");
const saudaveis = resultados.filter(x => x.nivel === "OK");

const capacidadeTotal = resultados.reduce((s, x) => s + (Number(x.limiteNumerico) || 0), 0);
const totalEnviadas24h = resultados.reduce((s, x) => s + (Number(x.enviadas24h) || 0), 0);

// ==========================================
// CAPACIDADE REAL DO PORTFOLIO (sem duplicar)
// Desde out/2025 a Meta compartilha o limite de mensageria
// por businessId (portfolio), não mais por número individual.
// Somar o tier de cada número conta a mesma cota várias vezes
// quando há mais de um BM no mesmo businessId.
// ==========================================

const tierPorBusinessId = {};
for (const item of resultados) {
    if (!item.businessId || !item.limiteNumerico) continue;
    // guarda o maior valor visto pro grupo (deveria ser sempre igual,
    // mas por segurança não assume consistência)
    const atual = tierPorBusinessId[item.businessId] || 0;
    tierPorBusinessId[item.businessId] = Math.max(atual, item.limiteNumerico);
}

const capacidadeRealPortfolio = Object.values(tierPorBusinessId).reduce((s, v) => s + v, 0);
const quantidadePortfoliosUnicos = Object.keys(tierPorBusinessId).length;

const distribuicaoQualidade = {};
for (const item of resultados) {
    const q = item.qualidade || "DESCONHECIDA";
    distribuicaoQualidade[q] = (distribuicaoQualidade[q] || 0) + 1;
}

const distribuicaoStatusMeta = {};
for (const item of resultados) {
    const s = item.statusMeta || "DESCONHECIDO";
    distribuicaoStatusMeta[s] = (distribuicaoStatusMeta[s] || 0) + 1;
}

// ==========================================
// GRUPOS: BMs no mesmo businessId (risco em cascata)
// ==========================================

const porBusinessId = {};
for (const item of resultados) {
    if (!item.businessId) continue;
    if (!porBusinessId[item.businessId]) porBusinessId[item.businessId] = [];
    porBusinessId[item.businessId].push({
        id: item.id, nome: item.nome, nivel: item.nivel, qualidade: item.qualidade
    });
}

const gruposComRiscoCompartilhado = Object.entries(porBusinessId)
    .filter(([, itens]) => itens.length > 1 && itens.some(i => i.nivel === "CRITICO"))
    .map(([businessId, itens]) => ({
        businessId,
        quantidadeNumeros: itens.length,
        numeros: itens
    }));

// ==========================================
// DIAGNÓSTICO EM TEXTO CORRIDO (leitura rápida)
// ==========================================

const nomesBanidos = criticos.filter(x => x.critico.includes("BANIDO_OU_RESTRITO_META")).map(x => x.nome);
const nomesQualidadeRed = criticos.filter(x => x.critico.includes("QUALIDADE_RED")).map(x => x.nome);
const nomesLimiteZerado = criticos.filter(x => x.critico.includes("LIMITE_DIARIO_ZERADO")).map(x => x.nome);
const nomesReprovados = emAtencao.filter(x => x.atencao.includes("NOME_EXIBICAO_REPROVADO")).map(x => x.nome);

const linhasDiagnostico = [];
if (nomesBanidos.length) linhasDiagnostico.push(`${nomesBanidos.length} conta(s) banida(s)/restrita(s) pela Meta: ${nomesBanidos.join(", ")}.`);
if (nomesQualidadeRed.length) linhasDiagnostico.push(`${nomesQualidadeRed.length} conta(s) com qualidade RED (risco alto de ban): ${nomesQualidadeRed.join(", ")}.`);
if (nomesLimiteZerado.length) linhasDiagnostico.push(`${nomesLimiteZerado.length} conta(s) já bateram o limite diário de mensagens: ${nomesLimiteZerado.join(", ")}.`);
if (nomesReprovados.length) linhasDiagnostico.push(`${nomesReprovados.length} conta(s) com nome de exibição reprovado (não bloqueia envio, mas vale corrigir): ${nomesReprovados.join(", ")}.`);
if (linhasDiagnostico.length === 0) linhasDiagnostico.push("Nenhum problema crítico identificado no momento.");

// ==========================================
// RETORNO FINAL
// ==========================================

return {
    sucesso: true,
    consultadoEm: new Date().toISOString(),

    diagnostico: linhasDiagnostico,

    resumo: {
        total,
        criticos: criticos.length,
        emAtencao: emAtencao.length,
        saudaveis: saudaveis.length,

        capacidadeTotal,
        capacidadeRealPortfolio,
        quantidadePortfoliosUnicos,
        totalEnviadas24h,
        percentualCapacidadeUsada: capacidadeRealPortfolio
            ? Math.round((totalEnviadas24h / capacidadeRealPortfolio) * 100)
            : null,

        distribuicaoQualidade,
        distribuicaoStatusMeta
    },

    alertas: {
        criticos: criticos.map(x => ({
            id: x.id, nome: x.nome, phoneNumber: x.phoneNumber, businessId: x.businessId,
            motivos: x.critico, statusMeta: x.statusMeta, qualidade: x.qualidade
        })),
        atencao: emAtencao.map(x => ({
            id: x.id, nome: x.nome, phoneNumber: x.phoneNumber, businessId: x.businessId,
            motivos: x.atencao
        })),
        gruposComRiscoCompartilhado
    },

    resultados
};
